package checkpointpolicy

import (
	"context"
	"fmt"

	"github.com/go-git/go-git/v6"
)

type UpdateOptions struct {
	CheckpointVersion    string
	CheckpointMinVersion string
	Force                bool
}

func Update(ctx context.Context, repo *git.Repository, target Target, opts UpdateOptions) (State, error) {
	baseline, err := updateBaseline(ctx, repo, target)
	if err != nil {
		return State{}, err
	}

	policy := baseline.Policy
	if opts.CheckpointVersion != "" {
		policy.CheckpointVersion = opts.CheckpointVersion
	}
	if opts.CheckpointMinVersion != "" {
		policy.CheckpointMinVersion = opts.CheckpointMinVersion
	}

	if err := rejectDowngrades(baseline.Policy, policy, opts); err != nil {
		return State{}, err
	}
	if err := ValidatePolicy(policy); err != nil {
		return State{}, err
	}

	hash, err := WriteLocal(ctx, repo, baseline.Hash, policy)
	if err != nil {
		return State{}, err
	}
	return State{
		Policy:     Normalize(policy),
		Source:     SourceLocal,
		Hash:       hash,
		RemoteHash: baseline.RemoteHash,
	}, nil
}

func updateBaseline(ctx context.Context, repo *git.Repository, target Target) (State, error) {
	local, err := ReadLocal(ctx, repo)
	if err != nil {
		return State{}, err
	}

	baseline, remoteFound, err := remoteBaseline(ctx, repo, target, local)
	if err != nil {
		return State{}, err
	}
	if !remoteFound || local.Hash == baseline.Hash {
		return baseline, nil
	}
	if local.Hash.IsZero() {
		return baseline, nil
	}
	localAncestor, err := isAncestorOf(ctx, repo, local.Hash, baseline.Hash)
	if err != nil {
		return State{}, err
	}
	if localAncestor {
		return baseline, nil
	}
	baselineAncestor, err := isAncestorOf(ctx, repo, baseline.Hash, local.Hash)
	if err != nil {
		return State{}, err
	}
	if baselineAncestor {
		local.RemoteHash = baseline.RemoteHash
		return local, nil
	}
	return State{}, fmt.Errorf("local checkpoint policy %s diverges from remote %s; push or reconcile the policy before updating", local.Hash, baseline.RemoteHash)
}

func rejectDowngrades(before, after Policy, opts UpdateOptions) error {
	before = Normalize(before)
	after = Normalize(after)

	if opts.Force {
		return nil
	}
	if opts.CheckpointVersion != "" {
		if err := rejectFieldDowngrade("checkpoint_version", before.CheckpointVersion, after.CheckpointVersion); err != nil {
			return err
		}
	}
	if opts.CheckpointMinVersion != "" {
		if err := rejectFieldDowngrade("checkpoint_min_version", before.CheckpointMinVersion, after.CheckpointMinVersion); err != nil {
			return err
		}
	}
	return nil
}

func rejectFieldDowngrade(field, beforeRaw, afterRaw string) error {
	before, err := ParseFormat(beforeRaw)
	if err != nil {
		return fmt.Errorf("%s existing value %q: %w", field, beforeRaw, err)
	}
	after, err := ParseFormat(afterRaw)
	if err != nil {
		return fmt.Errorf("%s: %w", field, err)
	}
	if Compare(after, before) < 0 {
		return fmt.Errorf("would downgrade %s from %q to %q; pass --force to allow this", field, beforeRaw, afterRaw)
	}
	return nil
}

// hook_guard.go protects against cross-agent hook forwarding. Cursor IDE
// invokes any hook configured under .claude/settings.json or .cursor/hooks.json
// for the active session — when only one of those files is installed, the
// other agent's hook command receives the event. shouldSkipForwardedHook
// detects this by inspecting the transcript path: if it lives inside another
// registered agent's session directory, the firing agent is forwarded and
// must no-op so the session isn't claimed for the wrong agent (#1262).
package cli

import (
	"context"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
)

// shouldSkipForwardedHook reports whether the firing agent should ignore this
// event because the transcript path proves it belongs to a different
// registered agent. Returns false when:
//   - event has no SessionRef (no signal — fail open)
//   - SessionRef is not inside any registered agent's session directory
//   - SessionRef belongs to the firing agent itself
//   - the worktree root cannot be resolved (fail open; downstream
//     handlers will surface the error)
func shouldSkipForwardedHook(ctx context.Context, ag agent.Agent, event *agent.Event) bool {
	if ag == nil || event == nil || event.SessionRef == "" {
		return false
	}
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return false
	}
	owner, ok := agent.AgentForTranscriptPath(event.SessionRef, repoRoot)
	if !ok {
		return false
	}
	return owner.Name() != ag.Name()
}

